function start(){driverName=document.getElementById('driverName').value.trim();localStorage.setItem('nsName',driverName);document.getElementById('driverbadge').textContent=driverName||'NIGHT DRIVER';skinColor=document.getElementById('skin').value;if(skinColor==='xwing'&&!hasXWing())skinColor='#29d7d5';localStorage.setItem('nsSkin',skinColor);score=0;speed=120;playerX=targetX=.5;driftVelocity=0;driftContinuous=0;driftGrace=0;spacePending=0;traffic=[];pickups=[];hazards=[];driftMarks=[];driftMarkTimer=0;spawn=.5;itemSpawn=2;roadOffset=0;lastCoin=0;skillTimers={filled:0,slow:0,berserker:0,sharpWay:0,cutTime:0};skillCooldowns={sharpWay:0,cutTime:0};turboTime=0;turboBurst=0;handCooldown=0;handFlash=0;timeOfDay=Math.random()<.5?'morning':'night';roadEvent='clear';eventTimer=60;updateSkill();playing=true;leaderRank=renderLeaderboard();last=performance.now();document.getElementById('eyebrow').textContent=`${timeOfDay.toUpperCase()} RUN · 01`;document.getElementById('title').innerHTML='NEON<br>DRIVE';document.getElementById('start').textContent='START ENGINE';overlay.classList.add('hidden');pop(`${timeOfDay.toUpperCase()} RUN`);if(musicOn){let m=document.getElementById('backgroundMusic');m.currentTime=0;m.play().catch(()=>{})}beep(520,.12);scheduleLoop()}
